package audio

import _ "embed"

// boopWAV is the volume-preview blip, generated by apps/config/tools/gen-boop.
//
//go:embed boop.wav
var boopWAV []byte

// PreviewBoop returns the volume-preview blip's WAV bytes, for registration
// via Service.LoadBytes.
func PreviewBoop() []byte { return boopWAV }

// stingerWAV is the boot stinger, generated by apps/boot/tools/gen-stinger.
// The microphone pipeline also uses it as a calibration signal.
//
//go:embed stinger.wav
var stingerWAV []byte

// Stinger returns the boot stinger's WAV bytes, for playback via
// Service.PlayBytes.
func Stinger() []byte { return stingerWAV }
